'use client'

import { useMemo } from 'react'
// Generated by `nextspark prepare` from entities/tasks: typed with the entity's own fields
import { useTasksList } from '@nextsparkjs/registries/entity-client/tasks.hooks'
import { calculateTaskStats, type TaskStats } from '../utils'

interface UseTaskStatsReturn {
  stats: TaskStats | null
  isLoading: boolean
  error: Error | null
  refetch: () => void
}

/**
 * Hook to fetch and calculate task statistics for the current team
 */
export function useTaskStats(): UseTaskStatsReturn {
  const { data, isLoading, error, refetch } = useTasksList({ limit: 1000 }, { staleTime: 1000 * 60 * 2 }) // 2 minutes

  const stats = useMemo(() => (data ? calculateTaskStats(data.data) : null), [data])

  return {
    stats,
    isLoading,
    error,
    refetch,
  }
}
